public class DatasetUtilities_iterateRangeBounds_TriageGen0Test {

    /**
     * Test standard XYDataset behavior (the 'else' block).
     */
    @Test
    public void testIterateRangeBounds_StandardXYDataset() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(2);
        // Item 0: 10.0, Item 1: 20.0
        when(dataset.getYValue(0, 0)).thenReturn(10.0);
        when(dataset.getYValue(0, 1)).thenReturn(20.0);

        Range range = DatasetUtilities.iterateRangeBounds(dataset, false);

        assertEquals(10.0, range.getLower(), 1e-9);
        assertEquals(20.0, range.getUpper(), 1e-9);
    }

    /**
     * Test IntervalXYDataset behavior when includeInterval is true.
     */
    @Test
    public void testIterateRangeBounds_IntervalXYDataset_IncludeInterval() {
        IntervalXYDataset ixyd = Mockito.mock(IntervalXYDataset.class);
        when(ixyd.getSeriesCount()).thenReturn(1);
        when(ixyd.getItemCount(0)).thenReturn(1);

        // Y=15, Start=5, End=25
        when(ixyd.getYValue(0, 0)).thenReturn(15.0);
        when(ixyd.getStartYValue(0, 0)).thenReturn(5.0);
        when(ixyd.getEndYValue(0, 0)).thenReturn(25.0);

        Range range = DatasetUtilities.iterateRangeBounds(ixyd, true);

        assertEquals(5.0, range.getLower(), 1e-9);
        assertEquals(25.0, range.getUpper(), 1e-9);
    }

    /**
     * Test IntervalXYDataset with NaNs to ensure they are skipped.
     */
    @Test
    public void testIterateRangeBounds_IntervalXYDataset_WithNaNs() {
        IntervalXYDataset ixyd = Mockito.mock(IntervalXYDataset.class);
        when(ixyd.getSeriesCount()).thenReturn(1);
        when(ixyd.getItemCount(0)).thenReturn(2);

        // Item 0: Valid Y=10, Start=5, End=15
        when(ixyd.getYValue(0, 0)).thenReturn(10.0);
        when(ixyd.getStartYValue(0, 0)).thenReturn(5.0);
        when(ixyd.getEndYValue(0, 0)).thenReturn(15.0);

        // Item 1: NaN values
        when(ixyd.getYValue(0, 1)).thenReturn(Double.NaN);
        when(ixyd.getStartYValue(0, 1)).thenReturn(Double.NaN);
        when(ixyd.getEndYValue(0, 1)).thenReturn(Double.NaN);

        Range range = DatasetUtilities.iterateRangeBounds(ixyd, true);

        assertEquals(5.0, range.getLower(), 1e-9);
        assertEquals(15.0, range.getUpper(), 1e-9);
    }

    /**
     * Test OHLCDataset behavior when includeInterval is true.
     */
    @Test
    public void testIterateRangeBounds_OHLCDataset_IncludeInterval() {
        OHLCDataset ohlc = Mockito.mock(OHLCDataset.class);
        when(ohlc.getSeriesCount()).thenReturn(1);
        when(ohlc.getItemCount(0)).thenReturn(1);

        // Low=10, High=50
        when(ohlc.getLowValue(0, 0)).thenReturn(10.0);
        when(ohlc.getHighValue(0, 0)).thenReturn(50.0);

        Range range = DatasetUtilities.iterateRangeBounds(ohlc, true);

        assertEquals(10.0, range.getLower(), 1e-9);
        assertEquals(50.0, range.getUpper(), 1e-9);
    }

    /**
     * Test OHLCDataset with NaNs.
     */
    @Test
    public void testIterateRangeBounds_OHLCDataset_WithNaNs() {
        OHLCDataset ohlc = Mockito.mock(OHLCDataset.class);
        when(ohlc.getSeriesCount()).thenReturn(1);
        when(ohlc.getItemCount(0)).thenReturn(2);

        when(ohlc.getLowValue(0, 0)).thenReturn(10.0);
        when(ohlc.getHighValue(0, 0)).thenReturn(20.0);

        when(ohlc.getLowValue(0, 1)).thenReturn(Double.NaN);
        when(ohlc.getHighValue(0, 1)).thenReturn(30.0);

        Range range = DatasetUtilities.iterateRangeBounds(ohlc, true);

        assertEquals(10.0, range.getLower(), 1e-9);
        assertEquals(30.0, range.getUpper(), 1e-9);
    }

    /**
     * Test the case where the dataset is empty or all values are NaN (returns null).
     */
    @Test
    public void testIterateRangeBounds_EmptyOrAllNaN() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getYValue(0, 0)).thenReturn(Double.NaN);

        Range range = DatasetUtilities.iterateRangeBounds(dataset, false);

        assertNull(range);
    }

    /**
     * Test the case where includeInterval is true but dataset is not Interval or OHLC.
     * It should fall back to the standard XYDataset loop.
     */
    @Test
    public void testIterateRangeBounds_IncludeInterval_ButNotSpecialType() {
        XYDataset dataset = Mockito.mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getYValue(0, 0)).thenReturn(100.0);

        // Even though includeInterval is true, it's a plain XYDataset, not IntervalXYDataset
        Range range = DatasetUtilities.iterateRangeBounds(dataset, true);

        assertEquals(100.0, range.getLower(), 1e-9);
        assertEquals(100.0, range.getUpper(), 1e-9);
    }
}
